import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IErpHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test refresh token success flow with token rotation validation.
 *
 * Validates the core session extension mechanism by registering a new guest account to obtain an initial JWT token pair, then exchanging the refresh token for a new pair via the refresh endpoint. Ensures token rotation is properly enforced and new tokens are valid for subsequent authenticated requests.
 *
 * 1. Guest joins to obtain the initial access token and refresh token.
 * 2. Call the refresh endpoint with the initial refresh token.
 * 3. Validate the new token pair: access token is present and refresh token has been rotated (different from the original).
 * 4. Validate expiration timestamps: both expired_at and refreshable_until are set in the future.
 * 5. Confirm the new access token can be used as a Bearer token for an authenticated request by performing a second refresh operation using the new token pair, proving the access token is valid for API calls.
 */
export async function test_api_refresh_token_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Guest joins to obtain initial tokens
  const guestConnection: api.IConnection = { host: connection.host };
  const joinResult = await authorize_guest_join(guestConnection, {});
  typia.assert(joinResult);
  const initialRefreshToken = joinResult.token.refresh;
  // 2. Call refresh endpoint with the initial refresh token
  const refreshConnection: api.IConnection = { host: connection.host };
  const refreshResult = await authorize_guest_refresh(refreshConnection, {
    body: {
      refresh_token: initialRefreshToken,
    } satisfies IErpHrmGuest.IRefresh,
  });
  typia.assert(refreshResult);
  // 3. Validate token rotation
  TestValidator.notEquals(
    "refresh token is rotated",
    refreshResult.token.refresh,
    initialRefreshToken,
  );
  TestValidator.predicate(
    "new access token is present",
    refreshResult.token.access.length > 0,
  );
  // 4. Validate expiration timestamps are in the future
  const now = new Date().toISOString();
  TestValidator.predicate(
    "expired_at is in the future",
    refreshResult.token.expired_at > now,
  );
  TestValidator.predicate(
    "refreshable_until is in the future",
    refreshResult.token.refreshable_until > now,
  );
  // 5. Confirm new access token works for authenticated requests
  const authenticatedConnection: api.IConnection = {
    host: connection.host,
    headers: { Authorization: refreshResult.token.access },
  };
  const secondRefreshResult = await authorize_guest_refresh(
    authenticatedConnection,
    {
      body: {
        refresh_token: refreshResult.token.refresh,
      } satisfies IErpHrmGuest.IRefresh,
    },
  );
  typia.assert(secondRefreshResult);
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IErpHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test refresh token reuse detection and replay attack prevention.
 *
 * Validates the single-use nature of refresh tokens through a token rotation
 * replay scenario. The test first obtains an initial refresh token (R1) via
 * guest registration, then consumes it through a successful refresh that issues
 * a new token (R2). Finally, it replays the already-consumed R1 and asserts
 * that the server rejects the replay with 401 Unauthorized.
 *
 * 1. Register a guest account to obtain the initial refresh token R1.
 * 2. Refresh using R1 — succeeds and returns a rotated refresh token R2.
 * 3. Verify R2 differs from R1, confirming token rotation occurred.
 * 4. Replay R1 — the server must detect the rotated token and return 401.
 */
export async function test_api_refresh_token_reuse_detection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Join as guest to obtain initial refresh token R1
  const guestConnection: api.IConnection = { host: connection.host };
  const initialAuth = await authorize_guest_join(guestConnection, {});
  typia.assert(initialAuth);
  const r1: string = initialAuth.token.refresh;
  // 2. Refresh with R1 — succeeds and issues rotated token R2
  const refreshConnection1: api.IConnection = { host: connection.host };
  const refreshedAuth = await authorize_guest_refresh(refreshConnection1, {
    body: { refresh_token: r1 } satisfies IErpHrmGuest.IRefresh,
  });
  typia.assert(refreshedAuth);
  TestValidator.notEquals(
    "R2 must differ from R1 after rotation",
    refreshedAuth.token.refresh,
    r1,
  );
  // 3. Replay R1 — server must detect rotated token and return 401
  const refreshConnection2: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "reuse of rotated refresh token is rejected with 401",
    401,
    async () => {
      await authorize_guest_refresh(refreshConnection2, {
        body: { refresh_token: r1 } satisfies IErpHrmGuest.IRefresh,
      });
    },
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IErpHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test that the refresh endpoint rejects fabricated, non-existent refresh tokens.
 *
 * Validates the security boundary of the token refresh mechanism by proving that
 * arbitrary, randomly generated tokens cannot be used to obtain authenticated
 * access. The system must look up the provided refresh_token in the
 * erp_hrm_member_sessions table and return 401 when no matching record exists.
 *
 * This test also implicitly validates that the refresh endpoint does not have
 * any fallback or default behavior that could allow token forgery — a completely
 * fabricated token must always result in rejection.
 *
 * 1. Register a guest account to establish that valid sessions can be created.
 * 2. Attempt to refresh with a randomly generated, non-existent refresh token.
 * 3. Verify the system returns 401 Unauthorized for the invalid token.
 */
export async function test_api_refresh_token_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Join as a guest to establish auth context (proves valid sessions exist)
  const guestConnection: api.IConnection = { host: connection.host };
  await authorize_guest_join(guestConnection, {});
  // 2. Attempt to refresh with a completely fabricated, non-existent refresh token
  await TestValidator.httpError(
    "fabricated refresh token returns 401",
    401,
    async () => {
      const invalidConnection: api.IConnection = { host: connection.host };
      await authorize_guest_refresh(invalidConnection, {
        body: {
          refresh_token: RandomGenerator.alphaNumeric(64),
        } satisfies IErpHrmGuest.IRefresh,
      });
    },
