  );
  TestValidator.equals(
    "active contract end_date is null",
    activeResult.data[0].end_date,
    null,
  );
  // 10. Validate past contract
  TestValidator.equals("past contracts count", pastResult.data.length, 1);
  TestValidator.equals(
