  // 3. Create a task with only the title — testing server-side defaults
  const task = await api.functional.erpHrm.member.projects.tasks.create(
    memberConnection,
    {
      projectId: project.id,
      body: {
        title: RandomGenerator.paragraph({ sentences: 1 }),
