  if (targetEmployee.status === "active") {
    const record = await MyGlobal.prisma.erp_hrm_employees.findFirstOrThrow({
      where: {
        id: props.employeeId,
        deleted_at: null,
      },
      ...ErpHrmEmployeeTransformer.select(),
